(() => {
  'use strict';
  const entries = [
    ['ἁπλοῦς','rule','Opening rule · circumflex','Listed as a polysyllabic simple word taking the circumflex.','ἁπλοῦς, διπλοῦς, τριπλοῦς, πλακοῦς.'],
    ['διπλοῦς','rule','Opening rule · circumflex','Listed alongside ἁπλοῦς, τριπλοῦς and πλακοῦς in the opening rule.','ἁπλοῦς, διπλοῦς, τριπλοῦς, πλακοῦς.'],
    ['τριπλοῦς','rule','Opening rule · circumflex','A further example of the opening rule for polysyllabic simple words in -ους.','ἁπλοῦς, διπλοῦς, τριπλοῦς, πλακοῦς.'],
    ['πλακοῦς','rule','Opening rule · circumflex','The fourth example printed in the opening list.','ἁπλοῦς, διπλοῦς, τριπλοῦς, πλακοῦς.'],
    ['Σχοινοῦς','place','Place name · Arcadia','The passage describes a marshy locality in Arcadia named from the rushes growing there.','Σχοινοῦς Ἀρκαδίας χωρίον.'],
    ['Σκιλλοῦς','place','Place name · Triphylia','A city of Triphylia, listed in the discussion of names taken from abundant local plants.','Σκιλλοῦς, πόλις Τριφυλική'],
    ['Τρεμιθοῦς','place','Place name · Cyprus · alternative accounts','A Cypriot village: the passage derives its name from local terebinths, called τρεμίθους by Cypriots. Others tell an alternative story involving Aphrodite and trembling; the passage reports both accounts.','Τρεμιθοῦς κώμη Κύπρου'],
    ['Δαφνοῦς','place','Place name · more than one locality','The passage names a Phocian city and also a deme near Cos with this name.','Δαφνοῦς Φωκικὴ πόλις'],
    ['Σελινοῦς','place','Place name · Sicily · grammatical gender','The Sicilian city is said to be spoken of in both the masculine and feminine.','Σελινοῦς πόλις Σικελίας ἀρσενικῶς καὶ θηλυκῶς λεγομένη'],
    ['Ἀγνοῦς','place','Place name · Athenian deme · variant attribution','Named from the ἄγνος growing there. The passage assigns the deme to Demetrias, while reporting that some assign it to Acamantis.','Ἀγνοῦς δῆμος τῆς Δημητριάδος φυλῆς']
  ];
  const $ = id => document.getElementById(id);
  const key = s => s.trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/ς/g,'σ');
  function show(entry) {
    $('resultWord').textContent = entry ? entry[0] : 'Not in this selected list';
    $('kind').textContent = entry ? entry[2] : 'No accent prediction';
    $('detail').textContent = entry ? entry[3] : 'Choose a listed example. An unfamiliar word cannot be classified from its ending alone.';
    $('source').textContent = entry ? entry[4] : '';
  }
  function lookup() {
    if (!$('word').value.trim()) {
      $('resultWord').textContent='Choose an example';$('kind').textContent='';
      $('detail').textContent='Select a word above, or enter one of the cited examples.';$('source').textContent='';return;
    }
    show(entries.find(e => key(e[0]) === key($('word').value)));
  }
  function list() {
    const visible=entries.filter(e=>$('group').value==='all'||e[1]===$('group').value);
    $('examples').replaceChildren();
    visible.forEach(e=>{const button=document.createElement('button');button.type='button';button.lang='grc';button.textContent=e[0];button.addEventListener('click',()=>{$('word').value=e[0];show(e);});$('examples').append(button);});
    $('count').textContent=visible.length+' selected examples';
  }
  $('word').addEventListener('input',lookup);$('group').addEventListener('change',list);
  $('reset').addEventListener('click',()=>{$('word').value='';$('group').value='all';list();lookup();$('word').focus();});
  list();lookup();
})();

