  const $=s=>document.querySelector(s);
  const first=['κνημίς','κρηπίς','σφραγίς','ἁψίς'];
  const pure=['Θαΐς','Λαΐς','Πτολεμαΐς','Κωπαΐς','Θηβαΐς','Κυρηναΐς','Ῥωμαΐς','Φωκαΐς','Βρισηΐς','Νηρηΐς','Αἰγηΐς','Ἰδηΐς','Ἀλυβηΐς','Δρυοπηΐς','Μεγαρηΐς'];
  const examples=first.concat(pure);
  const key=s=>s.trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/ς/g,'σ');
  function marks(s){return s.normalize('NFD').replace(/\u0308/g,'◌̈').replace(/\u0301/g,'◌́').replace(/\u0313/g,'◌̓').replace(/\u0314/g,'◌̔');}
  function run(){
    const raw=$('#in').value.trim();
    if(!raw){$('#outWord').textContent='—';$('#outExplain').textContent='Enter a selected example and choose Show spelling.';$('#syll').textContent='—';return;}
    const word=examples.find(w=>key(w)===key(raw));
    if(!word){$('#outWord').textContent=raw;$('#outExplain').textContent='Not in this selected list. No accent prediction is made.';$('#syll').textContent='—';return;}
    const showing=$('#toggleMarks').getAttribute('aria-pressed')==='true';
    $('#outWord').textContent=showing?marks(word):word;
    $('#outExplain').textContent=first.includes(word)?'Opening rule: final accent. This cited example is printed with an acute.':'Pure -ις list: final acute. The cited diaeresis and breathings are preserved.';
    const letters=Array.from(word.normalize('NFD').matchAll(/[^\u0300-\u036f][\u0300-\u036f]*/gu),m=>m[0].normalize('NFC')).join(' · ');
    $('#syll').textContent=showing?marks(letters):letters;
  }
  $('#go').addEventListener('click',run);
  $('#in').addEventListener('keydown',e=>{if(e.key==='Enter')run();});
  $('#clear').addEventListener('click',()=>{$('#in').value='';$('#toggleMarks').setAttribute('aria-pressed','false');$('#toggleMarks').textContent='Show combining marks';run();$('#in').focus();});
  $('#random').addEventListener('click',()=>{$('#in').value=examples[Math.floor(Math.random()*examples.length)];run();});
  $('#toggleMarks').addEventListener('click',()=>{const on=$('#toggleMarks').getAttribute('aria-pressed')!=='true';$('#toggleMarks').setAttribute('aria-pressed',String(on));$('#toggleMarks').textContent=on?'Hide combining marks':'Show combining marks';run();});
  run();
})();

